.dm-plb{position:relative;width:100%;max-width:440px;margin:0 auto;padding:16px}
.dm-plb-list,.dm-plb-one{display:flex;flex-direction:column;gap:12px}
.dm-plb-list[hidden],.dm-plb-one[hidden]{display:none}
.dm-plb-h{display:flex;align-items:center;gap:8px;min-height:32px}
.dm-plb-ht{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-plb-ht b{font-weight:500;font-size:14px}
.dm-plb-ht span{font-size:13px}
.dm-plb-back{margin-left:-6px;flex:none}
.dm-plb-rows{display:flex;flex-direction:column;margin:0 -8px}
.dm-plb-row{display:flex;align-items:center;gap:12px;width:100%;padding:9px 8px;border-radius:12px;text-align:left;color:var(--dm-fg);transition:background var(--dm-t-fast)}
.dm-plb-row:hover{background:var(--dm-row)}
.dm-plb-ic{width:32px;height:32px;border-radius:9px;background:var(--dm-chip);color:var(--dm-fg2);display:grid;place-items:center;flex:none}
.dm-plb-rt{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px}
.dm-plb-rt b{font-weight:500;font-size:13.5px}
.dm-plb-rt>span{font-size:13px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-plb-n{font-size:12px;color:var(--dm-muted);flex:none}
.dm-plb-row>svg:last-child{color:var(--dm-muted);flex:none}
.dm-plb-tp{margin:0;padding:10px 12px;border-radius:12px;background:var(--dm-chip);font-size:14px;line-height:1.8;color:var(--dm-fg)}
.dm-plb-s{padding:2px 5px;border-radius:6px;background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent));-webkit-box-decoration-break:clone;box-decoration-break:clone;transition:background .25s,color .25s,box-shadow .25s}
.dm-plb-s.dm-empty{background:var(--dm-surface);color:var(--dm-muted);box-shadow:inset 0 0 0 1px var(--dm-rail)}
.dm-plb-s.dm-bad{color:var(--dm-bad);box-shadow:inset 0 0 0 1px var(--dm-bad)}
.dm-plb-vars{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px}
.dm-plb-fd{display:flex;flex-direction:column;gap:5px;font-size:12.5px;font-weight:500;min-width:0}
.dm-plb-fd.dm-wide{grid-column:1/-1}
.dm-plb-in{width:100%;border:0;outline:0;border-radius:11px;background:var(--dm-chip);height:38px;padding:0 12px;font:inherit;font-size:13.5px;font-weight:400;color:var(--dm-fg);transition:box-shadow .25s,background .25s}
.dm-plb-in::placeholder{color:var(--dm-muted)}
.dm-plb-in:focus,.dm-plb-in.dm-ed{background:var(--dm-surface);box-shadow:inset 0 0 0 1.5px var(--dm-accent-mark,var(--dm-accent)),0 0 0 4px var(--dm-accent-bg)}
.dm-plb-fd.dm-bad .dm-plb-in{box-shadow:inset 0 0 0 1.5px var(--dm-bad)}
.dm-plb-er{font-size:12px;color:var(--dm-bad);font-weight:400}
.dm-plb-er[hidden]{display:none}
.dm-plb-sel{display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%;height:38px;padding:0 10px 0 12px;border-radius:11px;background:var(--dm-chip);font-size:13.5px;font-weight:400;color:var(--dm-fg);text-align:left;transition:background .2s,box-shadow .2s}
.dm-plb-sel:hover{background:var(--dm-row)}
.dm-plb-sel[aria-expanded="true"]{background:var(--dm-surface);box-shadow:inset 0 0 0 1.5px var(--dm-accent-mark,var(--dm-accent)),0 0 0 4px var(--dm-accent-bg)}
.dm-plb-sel>svg{color:var(--dm-muted);flex:none;transition:transform .32s var(--dm-ease)}
.dm-plb-sel[aria-expanded="true"]>svg{transform:rotate(180deg)}
.dm-plb-pop{min-width:180px}
.dm-plb-f{display:flex;align-items:center;gap:8px;min-height:32px}
.dm-plb-f .dm-sp{flex:1}
.dm-plb-note{font-size:13px}
.dm-plb-done{display:flex;align-items:center;gap:12px;padding:10px 10px 10px 12px;border-radius:12px;background:var(--dm-ok-bg);font-size:13.5px}
.dm-plb-done>svg{color:var(--dm-ok);flex:none}
.dm-plb-done .dm-t{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-plb-done .dm-t span{font-size:13px}
.dm-plb-done .dm-t .dm-muted{color:var(--dm-fg2)}
.dm-plb-done .dm-pill{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-shadow)}
.dm-plb-one.dm-used .dm-plb-vars{opacity:.55;transition:opacity .32s}

